package com.flippingfriend.companion;
import com.flippingfriend.core.*; import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementEligibilityContextComposerTest {
 private final BuyReplacementEligibilityContextComposer c=new BuyReplacementEligibilityContextComposer();
 @Test public void composesExactFreshAuthority(){BuyReplacementEligibilityContext x=c.compose(pending(1100),new BuyMaintenanceMarketInput(4151,990,1010,880),account(880,2000000,1,true),350,1000);assertNotNull(x);assertEquals("intent-1",x.getIntentId());assertEquals("offer-1",x.getOfferIdentity());assertEquals("plan-1",x.getRecommendationId());assertEquals(400,x.getRemainderQuantity());assertEquals(350,x.getBuyLimitRemaining());assertEquals(2000000,x.getSpendableCoins());}
 @Test public void freshnessBoundaryIsInclusive(){assertNotNull(c.compose(pending(1100),market(880),account(880,1,1,true),1,1000));assertNull(c.compose(pending(1100),market(879),account(880,1,1,true),1,1000));assertNull(c.compose(pending(1100),market(880),account(879,1,1,true),1,1000));}
 @Test public void invalidAuthorityFailsClosed(){assertNull(c.compose(base(1100),market(900),account(900,1,1,true),1,1000));assertNull(c.compose(pending(999),market(900),account(900,1,1,true),1,1000));assertNull(c.compose(pending(1100),new BuyMaintenanceMarketInput(1,990,1010,900),account(900,1,1,true),1,1000));assertNull(c.compose(pending(1100),market(900),account(900,0,1,true),1,1000));assertNull(c.compose(pending(1100),market(900),account(900,1,0,true),1,1000));assertNull(c.compose(pending(1100),market(900),account(900,1,1,false),1,1000));assertNull(c.compose(pending(1100),market(900),account(900,1,1,true),0,1000));}
 private static BuyMaintenanceMarketInput market(long at){return new BuyMaintenanceMarketInput(4151,990,1010,at);} private static AccountSnapshot account(long at,long coins,int slots,boolean bank){return new AccountSnapshot("a",at,coins,0,slots,8,true,bank,0);}
 private static BuyReplacementIntent base(long expires){return BuyReplacementIntent.cancelAuthorized("intent-1","offer-1","plan-1",2,4151,"Abyssal whip",1000,500,100,100,expires);} private static BuyReplacementIntent pending(long expires){BuyReplacementIntent i=base(expires);i=move(i,BuyReplacementIntentState.CANCEL_OBSERVED,110,true,false);i=move(i,BuyReplacementIntentState.COLLECTION_REQUIRED,110,false,false);i=move(i,BuyReplacementIntentState.ASSETS_RETURNED,120,false,true);return move(i,BuyReplacementIntentState.REPLACEMENT_ELIGIBILITY_PENDING,120,false,true);} private static BuyReplacementIntent move(BuyReplacementIntent i,BuyReplacementIntentState s,long at,boolean cancel,boolean collect){return BuyReplacementIntentTransition.apply(i,s,at,"offer-1","plan-1",cancel,collect,false);}
}
